 const docs=await rpc(p,'GET_PAGE',{page:{view:'library',limit:100}}),doc=docs.documents.find(row=>row.originalConversationTitle==='SYNTHETIC mixed removed inputs'),page=await rpc(p,'GET_PAGE',{page:{view:'library',documentId:doc.id,limit:100}}),inputs=page.library.blocks;assert.equal(inputs.length,3);for(const input of inputs)await rpc(p,'EXCLUDE_LIBRARY',{id:input.id,excluded:true});
 const parent=await rpc(p,'CREATE_LIBRARY_TOPIC',{topic:{name:'SYNTHETIC 保留的写作想法',operationId:operationId()}}),removedTopics=[];for(const name of ['SYNTHETIC 已移除写作想法','SYNTHETIC 已移除语言练习']){const topic=await rpc(p,'CREATE_LIBRARY_TOPIC',{topic:{name,operationId:operationId()}});await rpc(p,'REMOVE_LIBRARY_TOPIC',{edit:{id:topic.id,expectedRevision:topic.revision,operationId:operationId()}});removedTopics.push(topic);}
 const independent=await rpc(p,'CONTINUE_THINKING',{thought:{body:'SYNTHETIC 已移除的独立表达',operationId:operationId()}});const originalEntry=await rpc(p,'GET_LIBRARY_ENTRY',{id:independent.id});await rpc(p,'REMOVE_LIBRARY_ENTRY',{edit:{id:independent.id,expectedRevision:originalEntry.revision,operationId:operationId()}});
 const relations=[];for(const body of ['SYNTHETIC 一段写作练习','SYNTHETIC 一次表达练习']){const entry=await rpc(p,'CONTINUE_THINKING',{thought:{topicId:parent.id,body,operationId:operationId()}}),actual=await rpc(p,'GET_LIBRARY_ENTRY',{id:entry.id}),topic=await rpc(p,'GET_LIBRARY_TOPIC',{id:parent.id}),placement=await rpc(p,'GET_LIBRARY_PLACEMENT',{topicId:parent.id,entryId:entry.id});await rpc(p,'PLACE_LIBRARY_ENTRY',{placement:{entryId:entry.id,topicId:parent.id,expectedEntryRevision:actual.revision,expectedTopicRevision:topic.organizationRevision,expectedPlacementRevision:placement.revision,remove:true,operationId:operationId()}});relations.push({id:entry.id,body:actual.body});}
 const before={records:(await h.state()).records,context:await rpc(p,'PAIA_CONTEXT_CARDS_SNAPSHOT')};await p.setViewportSize({width:1440,height:900});await openData(p);await p.locator('#settings-removed').click();const dialog=p.locator('#settings-removed-dialog'),actions=dialog.locator('[data-recovery-kind]');await eventually(()=>actions.count().then(count=>count===8));assert.equal(await dialog.getByRole('button',{name:'重新加载列表',exact:true}).count(),0,'the ordinary approved modal has no fault-only reload destination');
 const contrast=async()=>{const result=await dialog.evaluate(node=>{const rgb=s=>(s.match(/[\d.]+/g)||[]).slice(0,3).map(Number),lum=c=>c.map(v=>{v/=255;return v<=.04045?v/12.92:((v+.055)/1.055)**2.4;}).reduce((n,v,i)=>n+v*[.2126,.7152,.0722][i],0);const texts=[...node.querySelectorAll('h2,p,button')].filter(el=>el.getClientRects().length&&!el.disabled);return{count:texts.length,min:Math.min(...texts.map(el=>{let parent=el,bg;while(parent){const value=getComputedStyle(parent).backgroundColor;if(value!=='transparent'&&value!=='rgba(0, 0, 0, 0)'){bg=rgb(value);break;}parent=parent.parentElement;}const a=lum(rgb(getComputedStyle(el).color)),b=lum(bg||[255,255,255]);return(Math.max(a,b)+.05)/(Math.min(a,b)+.05);}))};});assert.ok(result.count>=28,'actual populated native Removed heading/body/actions enter contrast sampling');assert.ok(result.min>=4.5,'actual native Removed text contrast: '+result.min);};await contrast();
